-- Выпуск 2, L4: переключение начислений людям с таблиц выплат на факты хаба с даты settings.payroll_facts_from (МСК).
-- Дни раньше неё начисляет таблица, как прежде, до цента; с неё — fact_accruals (доли продаж по правилам дележа по ставке
-- вкладки человека и фикс за день со сменой), на ту же вкладку человека модели. Таблица для этих дней — зеркало: читается
-- и сравнивается, не проводится. День, за который факты не отвечают (неделя не доказана, человек не сопоставлен с
-- пользователем хаба, долю не посчитать), остаётся как проведён и стоит в «не занесено» строкой unknown с причиной —
-- не ноль. Пустая настройка — только таблицы; откат — `ledger payroll facts-from --off`, пересборка вернёт книги таблиц.

INSERT INTO settings(key, value, note, updated_at) VALUES ('payroll_facts_from', '',
  'С какого дня (МСК) начисления людям — из фактов хаба (fact_accruals), а не из таблиц выплат; пусто — только таблицы. Ставит и снимает ledger payroll facts-from; откат — --off и пересборка',
  '2026-11-10T00:00:00+03:00')
ON CONFLICT(key) DO NOTHING;

ALTER TABLE payable_days ADD COLUMN source TEXT NOT NULL DEFAULT '';

INSERT INTO schema_docs(tbl, col, description) VALUES
 ('payable_days','source','Откуда день: sheet — таблица выплат, facts — факты хаба (с settings.payroll_facts_from); у не-дней пусто');

UPDATE schema_docs
   SET description = 'Дни вкладок: сумма дня в float точно как в таблице (процент по выручке дня плюс фикс поровну на дни с записями). Заменяются при каждом новом удачном разборе вкладки. С settings.payroll_facts_from дни таблицы — зеркало: начисляют факты хаба (fact_accruals), таблица только сравнивается'
 WHERE tbl = 'payroll_days' AND col = '';

UPDATE schema_docs
   SET description = '«Не занесено»: дни вкладок без значения за последние 45 дней, по которым хаб показывает деньги человека. В доказанную неделю фактов хаба (fact_weeks ok) у человека, сопоставленного с пользователем хаба, — его доли продаж за день (fact_accruals), день без его работы — выходной, не строка; иначе — деньги страниц недели в окне смены по карточке, но если окно смены лежит в доказанном окне фактов (hub_team_sync ok, с settings.hub_team_since), хаб видел человека до и после него, а смены на странице в окне не было, — выходной, не строка. День до дня, по который выплаты закрыли его долг (payable_days), не строка; вкладка модели, которой нет в непустом people.models, — без окна смены, только по фактам. С settings.payroll_facts_from дни начисляют факты, пустая ячейка таблицы — не пробел: строки этих дней только unknown с reason «факты хаба не начислили: …» — неделя не доказана, человек не сопоставлен с пользователем хаба или долю не посчитать (одна строка на вкладку и неделю или на день). Только сведения: в долг не идут'
 WHERE tbl = 'payroll_unentered' AND col = '';

UPDATE schema_docs
   SET description = 'Начисления из фактов: пользователь хаба × модель × страница × день → net его долей и сумма по ставке его вкладки модели. kind fix — фикс «Фикс/см» за день со сменой, страница пустая. Читать с fact_weeks: при unknown неделя «неизвестно», не ноль. С settings.payroll_facts_from суммы доказанных недель проводятся (accrual:payroll, source_key с «:facts») на вкладку человека модели; до неё — тень'
 WHERE tbl = 'fact_accruals' AND col = '';
